language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry fold(branch(leaf(4), leaf(4)));
}

language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry (let s = leaf(4) in fold(branch(s, s)));
}

language "moriarty-sherlock-nominal/1";
program P {
  type Schedule { Done; Pay(a_amount: UInt, b_next: UInt); }
  fn f(s: Schedule): Bool { s == 1 }
  entry f(construct Schedule::Done());
}

language "moriarty-sherlock-nominal/1";
program P {
  type Schedule { Done; Pay(a_amount: UInt, b_next: UInt); }
  fn f(s: Schedule): Bool { s == (true + 1) }
  entry f(construct Schedule::Done());
}
